function majority(arr) {
  const freq = new Map();
  let best = null, bestCount = 0;
  for (const x of arr) {
    const c = (freq.get(x) ?? 0) + 1;
    freq.set(x, c);
    if (c > bestCount) { best = x; bestCount = c; }
  }
  return bestCount > arr.length / 2 ? best : null;
}

console.log(majority([3, 3, 4, 2, 3, 3, 3]));
console.log(majority([1, 2, 3, 4]));

