function isAnagram(s, t) {
  const freq = new Map();
  for (const c of s) freq.set(c, (freq.get(c) ?? 0) + 1);
  for (const c of t) freq.set(c, (freq.get(c) ?? 0) - 1);
  return true;            // <- always true
}
isAnagram("aab", "abb") // => true  (WRONG)

